```go
func TestXxx3(t *testing.T) {
	server := httptest.NewUnstartedServer(
		http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("ok"))
		}),
	)

	server.EnableHTTP2 = true

	server.StartTLS()
	defer server.Close()

	tlsCfg := &gotls.Config{
		NextProtos:         []string{"h2", "http/1.1"},
		InsecureSkipVerify: true,
	}

	tr := &http.Transport{
		ForceAttemptHTTP2: true,
		DialTLSContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			conn, err := net.Dial(network, server.Listener.Addr().String())
			if err != nil {
				return nil, err
			}
			tlsConn := tls.UClient(conn, tlsCfg, &utls.HelloChrome_Auto)
			err = tlsConn.(*tls.UConn).HandshakeContext(ctx)
			// tlsConn := tls.Client(conn, tlsCfg)
			// err = tlsConn.(*tls.Conn).HandshakeContext(ctx)
			if err != nil {
				_ = conn.Close()
				return nil, err
			}
			state := tlsConn.(interface{ ConnectionState() gotls.ConnectionState }).ConnectionState()
			fmt.Println("NegotiatedProtocol", state.NegotiatedProtocol)
			return tlsConn, nil
		},
	}

	client := &http.Client{
		Transport: tr,
	}

	resp := common.Must2(client.Do(common.Must2(http.NewRequest("POST", "https://a.com/path", strings.NewReader("hello")))))
	fmt.Println(resp.Proto)
	resp.Body.Close()
}
```

