确认了，内层会是 a.com

```go
func TestXxx3(t *testing.T) {
	server := httptest.NewUnstartedServer(
		http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			fmt.Println("host", r.Host)
			w.Write([]byte("ok"))
		}),
	)

	server.TLS = &tls.Config{}

	server.TLS.GetConfigForClient = func(hello *tls.ClientHelloInfo) (*tls.Config, error) {
		fmt.Println("sni", hello.ServerName)
		return server.TLS, nil
	}

	server.StartTLS()
	defer server.Close()

	client := &http.Client{
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				return net.Dial(network, server.Listener.Addr().String())
			},
			TLSClientConfig: &tls.Config{
				InsecureSkipVerify: true,
				ServerName:         "b.com",
			},
		},
	}

	common.Must2(client.Do(common.Must2(http.NewRequest("POST", "https://a.com/path", strings.NewReader("hello"))))).Body.Close()
}
```

输出

```shell
sni b.com
host a.com
```

